mapper.select:
select t.pa_num paNum,t.machine_code machineCode,t.car_inout carInout,t.photo_jpg photoJpg, t.car_num carNum,t.remark,t.status_cd statusCd,t.ci_id ciId,t.inout_id inoutId, t.machine_id machineId,t.car_type carType,t.pa_id paId,t.state,t.community_id communityId, t.open_time openTime,t.in_time inTime,t.car_type_name carTypeName, td.name stateName,tcfc.fee_name feeName,tcfc.config_id configId, t.unlicense,t.color_type colorType,b.machine_name machineName, cm.name communityName from car_inout_his t left join t_dict td on t.state = td.status_cd and td.table_columns='state' and td.table_name = 'car_inout' left join parking_area pa on t.pa_id = pa.pa_id and pa.status_cd = '0' left join temp_car_fee_config tcfc on pa.pa_id = tcfc.pa_id and tcfc.status_cd = '0' and tcfc.car_type = t.color_type left join barrier b on t.machine_id = b.machine_id and b.community_id = t.community_id left join community cm on t.community_id = cm.community_id and cm.status_cd = '0' where 1=1
and t.community_id= #{communityId}
and t.car_num like concat('%',#{carNum},'%')
and t.car_num like concat('%',#{carNumLike},'%')
and t.open_time >= #{startTime}
and t.open_time <= #{endTime}
order by t.open_time desc
limit #{page}, #{row}

select count(1) count
from car_inout_his t
where 1=1

    and t.community_id= #{communityId}


    and t.car_num like concat('%',#{carNum},'%')


    and t.car_num like concat('%',#{carNumLike},'%')


    and t.open_time >= #{startTime}


    and t.open_time <= #{endTime}

mapper.delete:
delete from car_inout_his
where 1=1

    and community_id = #{communityId}


    and open_time >= #{startTime}


    and open_time <= #{endTime}
